    const phoneMatch=raw.match(/(?:\+?\d[\d\s().-]{7,}\d)/);
    const rawPhone=phoneMatch?.[0]?.trim()||''; const phone=rawPhone.replace(/\D/g,'').replace(/^91(?=\d{10}$)/,'');
