    const row={id:`P${index+1}`,raw,rawPhone,phone,name:'',nameOrigin:'',source:'',sourceExplicit:false,page:'',pageExplicit:false,pageOrigin:'',assistant:'',assistantOrigin:'',thirdParty:'',group:'',groupOrigin:'',status:'',statusExplicit:false,statusOrigin:'',phase:'',phaseOrigin:'',registered:'',hot:false,hotExplicit:false,investor:false,investorExplicit:false,note:'',confidence:phone.length===10?100:phone?35:0,issues:[]};const smart=window.ZhikeSmartImport?.parseNaturalLine?.(raw,state.channelAliases);if(smart){if(smart.name)row.name=smart.name;if(smart.source){row.source=smart.source;row.sourceExplicit=true;}if(smart.status){row.status=smart.status;row.statusExplicit=true;}if(smart.registered)row.registered=smart.registered;if(Number.isFinite(smart.confidence))row.confidence=Math.max(row.confidence,smart.confidence);}
