  function revalidateIntakeRows(){const phoneCounts=new Map();for(const row of state.parsed)if(row.phone)phoneCounts.set(row.phone,(phoneCounts.get(row.phone)||0)+1);const known=knownIntakePhones();let good=0,existingCount=0,bad=0;state.parsed.forEach((row,rowIndex)=>{row.issues=row.issues.filter(issue=>!['未识别号码','号码长度异常','同批重复'].includes(issue)&&!issue.startsWith('已存在：')&&!(row.channelConfirmed&&issue.startsWith('渠道存在歧义：')));if(!row.phone)row.issues.push('未识别号码');else if(row.phone.length!==10)row.issues.push('号码长度异常');const existing=known.get(row.phone);if(existing)row.issues.push(`已存在：${existing.name}`);if(row.phone&&phoneCounts.get(row.phone)>1)row.issues.push('同批重复');row.confidence=row.phone.length===10?(row.name?86:100):35;if(row.issues.length)row.confidence=Math.min(row.confidence,40);if(!row.issues.length&&row.phone.length===10)good++;else if(row.issues.some(issue=>issue.startsWith('已存在：')))existingCount++;else bad++;if(rowIndex>=100)return;const numberCell=$(`[data-normalized-phone="${rowIndex}"]`);if(numberCell)numberCell.textContent=row.phone||'未识别';const confidenceCell=$(`[data-parsed-row="${rowIndex}"] .confidence`);if(confidenceCell)confidenceCell.textContent=`${row.confidence}%`;const issueCell=$(`[data-parse-issues="${rowIndex}"]`);if(issueCell)issueCell.innerHTML=row.issues.length?`<span class="status-tag ${row.issues.some(issue=>issue.startsWith('已存在：'))?'tag-amber':'tag-red'}">${esc(row.issues.join('、'))}</span>`:'<span class="status-tag tag-green">可新增</span>';});const summary=$$('.parse-count');if(summary[0])summary[0].textContent=`可新增 ${good}`;if(summary[1])summary[1].textContent=`已存在 ${existingCount}`;if(summary[2])summary[2].textContent=`待检查 ${bad}`;}
  function parseIntake(){const lines=$('#intakeText')?.value||state.intakeText;state.intakeText=lines;parseIntakeLines(lines);renderIntake();}
  function intakeDefaults(){return state.settings.intakeDefaults||state.settings.intakeDraft?.defaults||{};}
  function currentIntakeDefaults(){const page=$('#defaultPage')?.value||'';return {source:normalizeBusinessSource($('#defaultSource')?.value,page),page,assistant:$('#defaultAssistant')?.value.trim()||'',group:$('#defaultGroup')?.value.trim()||'',status:$('#defaultStatus')?.value||'',phase:$('#defaultPhase')?.value||'',registered:$('#defaultRegistered')?.value||today,manualRegistered:Boolean($('#manualRegistered')?.checked),hot:Boolean($('#defaultHot')?.checked),investor:Boolean($('#defaultInvestor')?.checked)};}
  async function loadQuickIntakeFile(file){if(!file)return;try{if(file.size>24*1024*1024)throw new Error('文件超过 24 MB 上限');let tables=[];if(/\.xlsx?$|\.xlsm$/i.test(file.name)){if(!window.zhikeAI?.parseExcel)throw new Error('当前环境无法解析 Excel，请改用 CSV');const parsed=await window.zhikeAI.parseExcel({bytes:await file.arrayBuffer()});tables=parsed.tables||[];}else{const text=(await decodeCsvFile(file)).replace(/^\ufeff/,''),rows=parseCsv(text,detectCsvDelimiter(text));tables=[{name:file.name,rows}];}const mixedBusiness=tables.some(table=>{const headers=(table.rows?.[0]||[]).map(value=>String(value||'').trim()),mapping=csvHeaderMapping(headers);return mapping.recordType!=null||mapping.product!=null||mapping.amount!=null||mapping.followDate!=null||mapping.direction!=null||mapping.businessNote!=null;});if(mixedBusiness){toast('已识别混合业务列，切换到智能批量导入预览');await importCsvFiles([file]);return;}const lines=[];for(const table of tables){if(!table.rows?.length)continue;const headers=table.rows[0].map(value=>String(value||'').trim()),mapping=csvHeaderMapping(headers);if(mapping.phone==null)continue;for(const row of table.rows.slice(1)){const read=key=>mapping[key]==null?'':String(row[mapping[key]]||'').trim(),phone=read('phone');if(!phone)continue;const source=read('source'),parts=[phone,read('name'),source?`渠道:${source}`:'',read('page'),read('assistant')?`助理:${read('assistant')}`:'',read('group')?`群号:${read('group')}`:'',read('status'),read('phase'),read('registered'),read('note')].filter(Boolean);lines.push(parts.join('\t'));}}if(!lines.length)throw new Error('文件中没有识别到“手机号码”列或有效数据');const existing=($('#intakeText')?.value||state.intakeText||'').trim(),combined=[existing,lines.join('\n')].filter(Boolean).join('\n');state.intakeText=combined;parseIntakeLines(combined);renderIntake();toast(`已读取 ${lines.length} 行，渠道优先使用文件中的真实值`);}catch(error){toast(error.message||'快速录入文件读取失败','x');}}
