  function renderGroups(){const fanTypes=[...new Set(activeCustomers().filter(customer=>isGroupFanSource(customer.source)).map(customer=>customer.source))].sort((a,b)=>a.localeCompare(b,'zh-CN'));let sourceFilter=state.groupSource||'全部';if(sourceFilter!=='全部'&&sourceFilter!=='单导'&&!fanTypes.includes(sourceFilter)){sourceFilter='全部';state.groupSource='全部';}const {rows:all,summary,totalGroups}=groupSummaryRows(state.groupQuery||'',sourceFilter),single=summary.单导,group=summary.群粉;const pageCount=Math.max(1,Math.ceil(all.length/state.perPage));state.page=Math.min(state.page,pageCount);const start=(state.page-1)*state.perPage,groups=all.slice(start,start+state.perPage);const rows=groups.map(item=>`<tr><td>${sourceTag(item.source)}</td><td><strong>${esc(item.group)}</strong></td><td>${item.members}</td><td>${item.joined}</td><td>${item.left}</td><td>${item.hot}</td><td>${item.ticket}</td><td>${item.deposit}</td><td>${money(item.amount)}</td><td>${esc(item.assistant)}</td><td><button class="table-action" data-action="group-filter" data-source="${esc(item.source)}" data-group="${esc(item.group)}">查看成员</button></td></tr>`).join('');$('#viewContainer').innerHTML=heading('群组管理','单导与不同群粉类型都按群编号管理；无数据的群粉类型自动隐藏',btn('导出群组','download','export-filtered'))+`<div class="business-summary"><div class="business-kpi"><span>单导群组</span><strong>${single.groups}</strong></div><div class="business-kpi"><span>单导客户</span><strong>${single.customers}</strong></div><div class="business-kpi"><span>单导在群</span><strong>${single.joined}</strong></div><div class="business-kpi"><span>单导群组入金</span><strong>${money(single.amount)}</strong></div><div class="business-kpi"><span>群粉群组</span><strong>${group.groups}</strong></div><div class="business-kpi"><span>群粉客户</span><strong>${group.customers}</strong></div><div class="business-kpi"><span>群粉在群</span><strong>${group.joined}</strong></div><div class="business-kpi"><span>群粉群组入金</span><strong>${money(group.amount)}</strong></div></div><div class="subnav"><button data-group-source="全部" class="${sourceFilter==='全部'?'active':''}">全部群组</button><button data-group-source="单导" class="${sourceFilter==='单导'?'active':''}">单导群组</button>${fanTypes.map(type=>`<button data-group-source="${esc(type)}" class="${sourceFilter===type?'active':''}">${esc(type)}群组</button>`).join('')}</div><section class="panel table-panel"><div class="table-toolbar"><div class="table-context"><strong>${sourceFilter==='全部'?'全部':sourceFilter}群组表现</strong><span>显示 ${all.length?start+1:0}–${Math.min(start+state.perPage,all.length)} 条，共 ${all.length} 个匹配群组</span></div><label class="input-search">${icons('search')}<input data-search="group" value="${esc(state.groupQuery||'')}" placeholder="搜索群编号"></label></div><div class="table-scroll"><table class="data-table"><thead><tr>${['客户类型','群编号','客户数','在群','已退群','热聊','跟票','入金人数','入金金额','主要助理','操作'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||'<tr><td colspan="11" class="muted-cell">没有匹配的群组</td></tr>'}</tbody></table></div><div class="table-footer"><span>全部共 ${totalGroups} 个群组 · 当前显示 ${all.length} 个</span><div class="pagination"><button class="page-btn" data-page="${Math.max(1,state.page-1)}">‹</button><span>${state.page} / ${pageCount}</span><button class="page-btn" data-page="${Math.min(pageCount,state.page+1)}">›</button><select class="compact-select page-size"><option ${state.perPage===10?'selected':''}>10</option><option ${state.perPage===20?'selected':''}>20</option><option ${state.perPage===50?'selected':''}>50</option></select></div></div></section>`;}

  function renderAnalytics(){const n=counts(),list=activeCustomers(),sourceCounts=sources.map(source=>[source,list.filter(customer=>customer.source===source).length]).sort((a,b)=>b[1]-a[1]);$('#viewContainer').innerHTML=heading('统计分析','本地实时统计 · 点击分类可查看对应客户明细',btn('导出分析报告','download','export-filtered'))+`<div class="subnav"><button class="active">客户概览</button><button data-action="go-hot">热聊分析</button><button data-action="go-tickets">跟票分析</button><button data-action="go-deposits">入金分析</button><button data-action="go-groups">群组分析</button></div><div class="business-summary"><div class="business-kpi"><span>客户总数</span><strong>${n.total}</strong></div><div class="business-kpi"><span>进群率</span><strong>${Math.round(n.joined/Math.max(1,n.total)*100)}%</strong></div><div class="business-kpi"><span>热聊率</span><strong>${Math.round(n.hot/Math.max(1,n.total)*100)}%</strong></div><div class="business-kpi"><span>入金转化率</span><strong>${Math.round(n.deposit/Math.max(1,n.total)*100)}%</strong></div></div><section class="panel" style="margin-top:14px"><div class="panel-heading"><h2 class="panel-title">进退群统计</h2><span class="panel-note">今日变动与当前总量 · 单导和群粉分开</span></div>${renderStatusSummary(list)}</section><div class="two-col-content"><section class="panel"><div class="panel-heading"><h2 class="panel-title">渠道分布</h2><span class="panel-note">选择渠道查看客户</span></div><div class="funnel-content">${sourceCounts.map(([source,count])=>`<div class="funnel-row"><span style="width:95px;color:#697587;font-size:9px">${esc(source)}</span><div class="bar-small" style="flex:1"><i style="width:${Math.max(4,count/Math.max(1,n.total)*100)}%"></i></div><b style="font-size:9px;color:#536074;width:25px;text-align:right">${count}</b><button class="table-action" data-source="${esc(source)}">明细</button></div>`).join('')}</div></section><section class="panel"><div class="panel-heading"><h2 class="panel-title">转化漏斗</h2><span class="panel-note">本地客户库</span></div><div class="funnel-content">${[['新增客户',n.total],['已进群',n.joined],['热聊客户',n.hot],['跟票客户',n.ticket],['入金客户',n.deposit]].map(([label,value])=>`<div class="funnel-row"><div class="funnel-bar-wrap"><div class="funnel-bar" style="width:${Math.max(12,value/Math.max(1,n.total)*100)}%">${label}</div></div><strong class="funnel-num">${value}</strong></div>`).join('')}</div></section></div><section class="panel" style="margin-top:14px"><div class="panel-heading"><h2 class="panel-title">分类统计</h2><span class="panel-note">点击数字打开明细</span></div><div class="segment-summary">${sourceCounts.map(([source,count])=>[source,count,`source:${source}`]).concat([['未分配',n.unassigned,'assistant:未分配'],['缺少群号',n.missingGroup,'group:missing'],['热聊',n.hot,'hot:true'],['跟票',n.ticket,'ticket:true'],['入金',n.deposit,'deposit:true'],['已逾期',n.overdue,'follow:overdue']]).map(([label,value,key])=>`<button class="summary-tile" data-analytics-filter="${esc(key)}"><span>${esc(label)}</span><strong>${value}</strong><small>查看</small></button>`).join('')}</div></section>`;}
  function assistantSuggestionRows(){const cohorts=new Map();for(const c of activeCustomers()){if(!c.page||!c.assistant||c.assistant==='未分配')continue;const key=`${c.source}\u0000${c.page}`;if(!cohorts.has(key))cohorts.set(key,new Map());const counts=cohorts.get(key);counts.set(c.assistant,(counts.get(c.assistant)||0)+1);}const suggestions=[];for(const customer of activeCustomers().filter(c=>c.assistant==='未分配'&&c.page)){const key=`${customer.source}\u0000${customer.page}`,counts=cohorts.get(key);if(!counts)continue;const ranked=[...counts.entries()].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));const total=[...counts.values()].reduce((sum,n)=>sum+n,0);if(total<5||!ranked.length||ranked[0][1]/total<0.7)continue;suggestions.push({customer,assistant:ranked[0][0],matched:total,votes:ranked[0][1],share:ranked[0][1]/total});}return suggestions;}
  function renderAssistantSuggestions(){const all=assistantSuggestionRows();const pages=[...new Set(all.map(row=>row.customer.page))].sort((a,b)=>a.localeCompare(b,'zh-CN'));const pageFilter=state.assistantSuggestionPageFilter||'全部来源页面';const rows=pageFilter==='全部来源页面'?all:all.filter(row=>row.customer.page===pageFilter);const pageSize=50;const pageCount=Math.max(1,Math.ceil(rows.length/pageSize));state.assistantSuggestionPage=Math.min(state.assistantSuggestionPage||1,pageCount);const start=(state.assistantSuggestionPage-1)*pageSize;const visible=rows.slice(start,start+pageSize);const pageOptions=['全部来源页面',...pages].map(page=>`<option value="${esc(page)}" ${page===pageFilter?'selected':''}>${esc(page)}</option>`).join('');$('#viewContainer').innerHTML=heading('助理分配建议','按来源页面筛选 · 每次只查看 50 条 · 应用前需人工确认',btn('返回自动化','chevron-left','automation-overview'))+`<div class="notice-line">仅展示至少 5 条历史样本且首选助理占比达到 70% 的建议。不会自动分配，确认前不会修改客户资料。</div><div class="business-summary"><div class="business-kpi"><span>高置信建议</span><strong>${all.length}</strong></div><div class="business-kpi"><span>当前筛选</span><strong>${rows.length}</strong></div><div class="business-kpi"><span>历史样本门槛</span><strong>5 条</strong></div><div class="business-kpi"><span>建议占比门槛</span><strong>70%</strong></div></div><section class="panel table-panel"><div class="table-toolbar"><div class="table-context"><strong>按来源页面推荐</strong><span>显示 ${rows.length?start+1:0}–${Math.min(start+pageSize,rows.length)} 条，共 ${rows.length} 条</span></div><div class="toolbar-controls"><label class="filter-field"><span>来源页面</span><select data-assistant-page>${pageOptions}</select></label><button class="btn small primary" data-action="apply-all-assistant-suggestions" ${rows.length?'':'disabled'}>确认应用当前筛选建议 (${rows.length})</button></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>客户</th><th>号码</th><th>来源页面</th><th>推荐助理</th><th>历史依据</th><th>操作</th></tr></thead><tbody>${visible.map(({customer,assistant,matched,votes,share})=>`<tr><td>${esc(customer.name)}</td><td class="phone-cell">${esc(customer.rawPhone||'')}</td><td>${esc(customer.page)}</td><td><span class="status-tag tag-blue">${esc(assistant)}</span></td><td>${votes}/${matched} 条历史 · ${Math.round(share*100)}%</td><td><button class="table-action" data-action="apply-assistant-suggestion" data-id="${esc(customer.id)}">确认分配</button></td></tr>`).join('')||'<tr><td colspan="6" class="muted-cell">当前来源页面没有达到门槛的建议</td></tr>'}</tbody></table></div><div class="table-footer"><span>每页 ${pageSize} 条</span><div class="pagination"><button class="page-btn" data-action="assistant-suggestion-page" data-page="${Math.max(1,state.assistantSuggestionPage-1)}" ${state.assistantSuggestionPage===1?'disabled':''}>‹</button><span>${state.assistantSuggestionPage} / ${pageCount}</span><button class="page-btn" data-action="assistant-suggestion-page" data-page="${Math.min(pageCount,state.assistantSuggestionPage+1)}" ${state.assistantSuggestionPage===pageCount?'disabled':''}>›</button></div></div></section>`;}
  async function applyAssistantSuggestions(ids){if(state.settings.assistantSuggestions===false){toast('助理分配建议已暂停');return;}const pageFilter=state.assistantSuggestionPageFilter||'全部来源页面';const suggestions=assistantSuggestionRows().filter(row=>(!ids||ids.includes(String(row.customer.id)))&&(ids||pageFilter==='全部来源页面'||row.customer.page===pageFilter));if(!suggestions.length){toast('当前筛选没有可应用的高置信建议');return;}const detail=ids?`${suggestions[0].customer.name} → ${suggestions[0].assistant}`:`当前筛选中的 ${suggestions.length} 位客户`;if(!confirm(`确认应用${detail}？分配结果将记录在本机，可在客户资料中修改。`))return;if(!await snapshotBeforeWrite('应用助理分配建议前自动快照'))return;const targetIds=new Set(suggestions.map(row=>String(row.customer.id)));const current=assistantSuggestionRows().filter(row=>targetIds.has(String(row.customer.id))&&(ids||pageFilter==='全部来源页面'||row.customer.page===pageFilter));if(!current.length){toast('建议条件已变化，没有应用任何分配');return;}const previous=current.map(row=>({customer:row.customer,assistant:row.customer.assistant,touched:row.customer.touched}));const previousActivities=state.activities.slice();for(const row of current){row.customer.assistant=row.assistant;row.customer.touched=true;}const detailLines=current.slice(0,10).map(row=>`${row.customer.name}→${row.assistant}`);const suffix=current.length>detailLines.length?`，另 ${current.length-detailLines.length} 位`:' ';activity(`人工确认助理分配 ${current.length} 条：${detailLines.join('；')}${suffix}`.trim());try{await flushStateWrites();}catch{for(const row of previous){row.customer.assistant=row.assistant;row.customer.touched=row.touched;}state.activities=previousActivities;persist();toast('本机数据库写入失败，已撤销本次分配','x');render();return;}render();toast(`已应用并保存 ${current.length} 条建议`);}
  function renderAutomation(){const rules=[
    ['normalize','号码标准化','录入和导入时统一号码格式，作为数据校验基础',true,false],
    ['channel','渠道分类识别','按系统设置中的渠道选项对录入资料进行归类',true,false],
    ['duplicateGuard','重复号码保护','导入仅新增号码，已存在客户不会被覆盖',true,false],
    ['dueReminder','逾期任务提醒','按计划日期汇总到客户中心与今日工作台',true,false],
    ['preWriteSnapshot','写入前自动快照','批量导入、迁移和恢复前保留可回退数据',true,false],
    ['autoInitialFollow','快速录入后创建次日跟进','仅影响快速录入新增客户；可在录入页单独关闭',state.settings.autoInitialFollow!==false,true],
    ['staleHotReminder','热聊未跟进提醒','在自动化发现区提示超过 3 天未跟进的热聊客户',state.settings.staleHotReminder!==false,true],
    ['assistantSuggestions','助理分配建议','按来源页面历史给出建议，必须人工确认才会写入',state.settings.assistantSuggestions!==false,true],
  ];
    const enabledCount=rules.filter(rule=>rule[3]).length;
    const ruleRows=rules.map(([key,name,desc,on,configurable])=>`<div class="suggestion automation-rule-row"><div class="suggestion-icon blue">${icons('spark')}</div><div class="suggestion-copy"><strong>${name}</strong><p>${desc}</p></div>${configurable?`<button class="switch ${on?'on':''}" data-rule="${key}" aria-label="${on?'关闭':'启用'}${name}" aria-pressed="${on}" title="${on?'当前启用':'当前关闭'}"></button>`:'<span class="status-tag tag-green automation-rule-state">固定运行</span>'}</div>`).join('');
    const discoveries=`${suggestion('clock','red',`${counts().overdue} 位客户已逾期`,'根据登记日期自动汇总。','查看明细','go-followups')}${suggestion('users','blue',`${counts().unassigned} 位客户未分配助理`,'根据负责人字段为空的记录识别。','查看客户','unassigned')}${suggestion('shield','',`${counts().missingGroup} 位客户缺少群编号`,'不会自动填入，需人工确认。','数据治理','go-quality')}${state.settings.staleHotReminder!==false?suggestion('clock','orange',`${staleHotCustomers().length} 位热聊客户超过 3 天未跟进`,'使用最后跟进日期识别，只提醒、不自动修改客户资料。','查看名单','go-hot-stale'):''}${state.settings.assistantSuggestions!==false&&assistantSuggestionRows().length?suggestion('users','blue',`${assistantSuggestionRows().length} 条高置信助理建议`,'至少 5 条同页面历史样本且首选占比达到 70%，应用前需确认。','查看建议','go-assistant-suggestions'):''}`;
    $('#viewContainer').innerHTML=heading('本地自动化','规则完全在本机运行 · 数据安全保护始终启用',btn('查看执行记录','history','go-activity'))+`<div class="notice-line">所有规则只读取本机客户库。可配置项会立即生效；号码规范化、重复保护和写入前快照固定运行。</div><div class="two-col-content"><section class="panel"><div class="panel-heading"><h2 class="panel-title">自动化规则</h2><span class="status-tag tag-green">${enabledCount} 条启用 · ${rules.filter(rule=>!rule[4]).length} 条固定运行</span></div><div style="padding:0 17px">${ruleRows}</div></section><section class="panel"><div class="panel-heading"><h2 class="panel-title">今日本地发现</h2><span class="panel-note">可配置提醒只影响此处建议，不会隐藏客户记录</span></div><div class="suggestion-list">${discoveries}</div></section></div>`;}
  function phoneForQuality(customer){const clean=value=>{const digits=String(value||'').replace(/\D/g,'');return digits.length===12&&digits.startsWith('91')?digits.slice(2):digits;};const primary=clean(customer.phone);return primary.length===10?primary:clean(customer.rawPhone)||primary;}
  function qualityScan(){const groups=new Map();for(const customer of activeCustomers()){const phone=phoneForQuality(customer);if(phone.length===10){if(!groups.has(phone))groups.set(phone,[]);groups.get(phone).push(customer);}}const duplicates=[...groups.values()].filter(group=>group.length>1).flat();const invalid=activeCustomers().filter(c=>phoneForQuality(c).length!==10);return {duplicates,invalid};}
  function duplicateCustomerPlan(){const groups=new Map(),businessIds=new Set([...state.tickets,...state.deposits,...state.followups,...state.registrations].map(row=>String(row.customerId)));for(const customer of activeCustomers()){const phone=phoneForQuality(customer);if(phone.length!==10)continue;if(!groups.has(phone))groups.set(phone,[]);groups.get(phone).push(customer);}const survivors=[],duplicates=[];for(const [phone,group] of groups){if(group.length<2)continue;const score=customer=>['name','source','page','assistant','status','phase','qualification','group','note','lastFollow','due'].reduce((sum,key)=>sum+(customer[key]&&customer[key]!=='—'&&customer[key]!=='未分配'?1:0),0)+(customer.touched?3:0)+(customer.favorite?2:0)+(businessIds.has(String(customer.id))?4:0)+(customer.hot?1:0);const ranked=group.slice().sort((a,b)=>score(b)-score(a)||String(a.registered||'').localeCompare(String(b.registered||''))||String(a.id).localeCompare(String(b.id))),survivor=ranked[0];survivors.push({phone,survivor,removed:ranked.slice(1)});duplicates.push(...ranked.slice(1));}return {survivors,duplicates};}
  function deduplicatePreview(){const plan=duplicateCustomerPlan();if(!plan.duplicates.length){toast('当前没有可删除的重复号码');return;}const preview=plan.survivors.slice(0,12).map(item=>`<div class="batch-preview-name"><strong>${esc(item.phone)}</strong> · 保留 ${esc(item.survivor.name)} · 移除 ${item.removed.map(c=>esc(c.name)).join('、')}</div>`).join('');openModal('删除重复值',`按标准化手机号码去重 · ${plan.survivors.length} 组`,`${`<div class="batch-preview-summary"><div><span>重复号码</span><strong>${plan.survivors.length}</strong></div><div><span>保留客户</span><strong>${plan.survivors.length}</strong></div><div><span>移入回收站</span><strong>${plan.duplicates.length}</strong></div></div>`}<div class="notice-line">自动保留资料更完整、有业务关联或已人工修改的记录。其余重复值仅移入回收站，不会永久删除。</div><div class="batch-preview-list">${preview}${plan.survivors.length>12?`<span>另有 ${plan.survivors.length-12} 组未在预览中展开</span>`:''}</div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="apply-deduplicate-customers">确认删除重复值</button>`);}
  async function applyDeduplicateCustomers(){const plan=duplicateCustomerPlan();if(!plan.duplicates.length){closeModal();toast('重复数据已发生变化，当前无需处理');return;}if(!await snapshotBeforeWrite('删除重复值前自动快照'))return;const now=new Date().toISOString();for(const customer of plan.duplicates){customer.deleted=true;customer.deletedAt=now;customer.duplicateOf=plan.survivors.find(item=>item.removed.includes(customer))?.survivor.id||'';}persist();activity(`删除重复值：${plan.survivors.length} 组，${plan.duplicates.length} 位客户移入回收站`);try{await flushStateWrites();}catch{for(const customer of plan.duplicates){customer.deleted=false;delete customer.deletedAt;delete customer.duplicateOf;}persist();toast('本机数据库保存失败，已恢复全部重复记录','x');return;}closeModal();render();toast(`已删除 ${plan.duplicates.length} 条重复值，可在回收站恢复`);}
  function pendingImportIssues(){return state.importIssues.filter(x=>!x.resolved&&!x.ignored);}
  function importIssueModal(issue){const v=issue.values||{};const select=(key,label,options,value,optional=false)=>`<label class="filter-field"><span>${label}</span><select id="issue-${key}">${optional?'<option value="">不指定</option>':''}${options.map(option=>`<option value="${esc(option)}" ${option===value?'selected':''}>${esc(option)}</option>`).join('')}</select></label>`;const field=(key,label,type='text')=>`<label class="filter-field"><span>${label}</span><input id="issue-${key}" type="${type}" value="${esc(v[key]||'')}" placeholder="${label}"></label>`;const source=sources.includes(v.source)?v.source:(/群粉/.test(`${v.source||''} ${v.page||''}`)?'群粉':'单导');const pagesForIssue=[...new Set([...pages,v.page||''].filter(Boolean))];openModal('复核导入行',`${esc(issue.file)} · 第 ${issue.row} 行 · ${esc(issue.reason)}`,`<div class="notice-line">修正后会按“渠道 + 可选页面”保存，页面可以用于群粉或其他渠道。</div><div class="filter-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${field('name','客户姓名')}${field('phone','手机号码','tel')}${select('source','渠道',sources,source)}${select('page','页面分类',pagesForIssue,v.page||'',true)}${select('assistant','跟进助理',assistants,v.assistant||'未分配')}${select('status','进群状态',statuses,v.status||(isGroupFanSource(source)?'在群':'未进群'))}${select('phase','客户阶段',phases,v.phase||'新客户')}${field('group','群编号')}${field('registered','登记日期','date')}<label class="filter-field" style="grid-column:1/-1"><span>备注</span><input id="issue-note" value="${esc(v.note||'')}"></label></div><div class="timeline"><h3>原始 CSV 行</h3><div class="notice-line">${esc(issue.raw)}</div></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn danger" data-action="ignore-import-issue" data-id="${esc(issue.id)}">确认忽略</button><button class="btn primary" data-action="retry-import-issue" data-id="${esc(issue.id)}">修正并重试</button>`);}
  function retryImportIssue(id){const issue=state.importIssues.find(x=>String(x.id)===String(id));if(!issue)return;const values=Object.fromEntries(['name','phone','source','page','assistant','status','phase','group','registered','note'].map(k=>[k,$(`#issue-${k}`)?.value.trim()||'']));const phone=linkedPhone(values.phone);if(phone.length!==10){toast('请先修正为有效的 10 位标准号码','x');return;}if(knownIntakePhones().has(phone)){toast('该号码已存在，请核对客户资料后处理此行','x');return;}const source=values.source||'单导';if(!sources.includes(source))sources.push(source);if(values.page&&!pages.includes(values.page))pages.push(values.page);const customer={id:`C${Date.now()}-${Math.random().toString(36).slice(2,7)}`,name:values.name||'未命名客户',rawPhone:values.phone,phone,source,page:values.page,channel:source,assistant:values.assistant||'未分配',status:values.status||'未进群',phase:values.phase||'新客户',hot:false,investor:false,group:values.group||'—',ticket:false,deposit:false,amount:0,registered:values.registered?values.registered.slice(0,10):today,lastFollow:'',due:today,note:values.note||'',deleted:false,touched:false};state.customers.unshift(customer);intakePhoneIndex=null;issue.originalValues=issue.originalValues||structuredClone(issue.values||{});issue.values=values;issue.resolved=true;issue.resolvedAt=new Date().toISOString();issue.resolvedCustomerId=customer.id;persist();activity(`复核导入行并新增客户 ${customer.name}`);closeModal();render();toast('已修正并导入客户');}
  function ignoreImportIssue(id){const issue=state.importIssues.find(x=>String(x.id)===String(id));if(!issue)return;if(!confirm('确认忽略该行？原始内容仍会保留，可在已处理记录中撤销。'))return;issue.ignored=true;issue.ignoredAt=new Date().toISOString();persist();activity(`确认忽略导入待复核行：${issue.file} 第 ${issue.row} 行`);closeModal();render();toast('已标记忽略，原始记录仍保留');}
  function renderQuality(){const n=counts();const scan=qualityScan();const pendingDuplicates=scan.duplicates.filter(c=>!state.qualityDecisions[String(c.id)]?.duplicate);const pendingInvalid=scan.invalid.filter(c=>!state.qualityDecisions[String(c.id)]?.invalid);if(state.qualityView==='duplicates'||state.qualityView==='invalid'){const type=state.qualityView;const all=type==='duplicates'?scan.duplicates:scan.invalid;const pending=type==='duplicates'?pendingDuplicates:pendingInvalid;const list=state.qualityShowReviewed?all:pending;const rows=list.map(c=>{const reviewed=Boolean(state.qualityDecisions[String(c.id)]?.[type]);const related=type==='duplicates'?scan.duplicates.filter(x=>phoneForQuality(x)===phoneForQuality(c)).length:0;return `<tr data-customer="${esc(c.id)}"><td>${esc(c.name)}</td><td class="phone-cell">${esc(c.rawPhone||'')}</td><td>${esc(phoneForQuality(c)||'—')}</td><td>${type==='duplicates'?`${related} 条共享号码`:'号码位数异常'}</td><td>${reviewed?'<span class="status-tag tag-green">已复核保留</span>':'<span class="status-tag tag-amber">待复核</span>'}</td><td>${type==='invalid'?`<button class="table-action" data-action="edit-customer" data-id="${esc(c.id)}">编辑号码</button>`:''}<button class="table-action" data-action="${reviewed?'undo-quality-review':'review-quality'}" data-id="${esc(c.id)}" data-type="${type}">${reviewed?'撤销复核':type==='duplicates'?'确认保留':'确认保留原号'}</button></td></tr>`}).join('');$('#viewContainer').innerHTML=heading(type==='duplicates'?'重复号码复核':'异常号码复核','仅标记复核状态，不会自动合并、删除或改写客户资料',btn('返回治理','chevron-left','quality-overview'))+`<div class="notice-line">${type==='duplicates'?'共享同一标准号码的客户会并列展示。逐条确认后记录仍保留，可随时撤销复核。':'号码长度不符合本地规则的记录会保留原值；可进入编辑修正，或确认该号码为特殊情况。'}</div><section class="panel table-panel"><div class="table-toolbar"><div class="table-context"><strong>${list.length} 条${state.qualityShowReviewed?'记录':'待复核'}</strong><span>总计 ${all.length} 条</span></div><button class="btn small" data-action="toggle-quality-reviewed">${state.qualityShowReviewed?'仅看待复核':'显示已复核'}</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>客户</th><th>原始号码</th><th>标准号码</th><th>检查结果</th><th>处理状态</th><th>操作</th></tr></thead><tbody>${rows||'<tr><td colspan="6" class="muted-cell">当前没有待复核记录</td></tr>'}</tbody></table></div></section>`;return;}
    const pending=pendingImportIssues();const processed=state.importIssues.filter(x=>x.resolved||x.ignored);const sorted=[...pending,...processed];const rows=sorted.slice(0,100).map(x=>{const status=x.resolved?'<span class="status-tag tag-green">已导入</span>':x.ignored?'<span class="status-tag">已忽略</span>':'<span class="status-tag tag-amber">待复核</span>';const v=x.values||{};const actions=x.resolved?`<button class="table-action" data-action="show-import-customer" data-id="${esc(x.resolvedCustomerId||'')}">查看客户</button>`:x.ignored?`<button class="table-action" data-action="restore-import-issue" data-id="${esc(x.id)}">撤销忽略</button>`:`<button class="table-action" data-action="edit-import-issue" data-id="${esc(x.id)}">修正/重试</button><button class="table-action" data-action="ignore-import-issue" data-id="${esc(x.id)}">忽略</button>`;return `<tr><td>${esc(x.file)}</td><td>${x.row}</td><td>${status}</td><td>${esc(x.reason)}</td><td>${esc(v.name||'')} · ${esc(v.phone||'')}</td><td>${esc(v.channel||'未识别')}</td><td>${actions}</td></tr>`}).join('');const issueCount=pending.length;const summaryRows=[['缺少群编号',n.missingGroup,'群编号为空或未识别','missing-group'],['未分配助理',n.unassigned,'未设置跟进负责人','unassigned'],['号码重复',pendingDuplicates.length,'共享标准号码的客户记录','quality-duplicates'],['号码异常',pendingInvalid.length,'号码缺失或标准号码长度不是 10 位','quality-invalid'],['导入待复核',issueCount,'异常或重复的 CSV 行，可逐条修正、重试或忽略','export-import-issues'],['资料待完善',n.missingGroup+n.unassigned,'关键客户字段缺失','incomplete']];$('#viewContainer').innerHTML=heading('数据治理','集中处理重复、异常和资料缺失 · 修复与忽略均保留审计记录',btn('重新检查','history','quality-scan'))+`<div class="business-summary">${[['号码重复',pendingDuplicates.length],['号码异常',pendingInvalid.length],['导入待复核',issueCount],['已处理导入行',processed.length]].map(([label,value])=>`<div class="business-kpi"><span>${label}</span><strong>${value}</strong><small>条记录</small></div>`).join('')}</div><section class="panel"><div class="panel-heading"><h2 class="panel-title">待处理问题</h2><span class="panel-note">导入行可单条修正后重试，或确认忽略</span></div><table class="task-table"><thead><tr><th>问题类型</th><th>数量</th><th>检查规则</th><th>操作</th></tr></thead><tbody>${summaryRows.map(([l,v,d,a])=>`<tr><td><strong>${l}</strong></td><td>${v}</td><td>${d}</td><td><button class="table-action" data-action="${a}">查看名单 ${icons('chevron-right')}</button></td></tr>`).join('')}</tbody></table></section>${state.importIssues.length?`<section class="panel table-panel" style="margin-top:14px"><div class="panel-heading"><h2 class="panel-title">CSV 导入行审计</h2><span class="panel-note">显示前 ${Math.min(100,state.importIssues.length)} 条 · ${issueCount} 条待复核 · ${processed.length} 条已处理</span><button class="btn small" data-action="export-import-issues">导出完整审计 CSV</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>来源文件</th><th>行号</th><th>状态</th><th>原问题</th><th>姓名 · 号码</th><th>渠道</th><th>操作</th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="muted-cell">没有导入记录</td></tr>'}</tbody></table></div><div class="table-footer"><button class="table-action" data-action="clear-import-issues">清理已处理记录 (${processed.length})</button></div></section>`:''}`;}
  function renderData(){const n=counts();$('#viewContainer').innerHTML=heading('数据中心','本机数据的导入、导出、备份与迁移',btn('立即备份','cloud-down','backup','primary'))+`<div class="business-summary"><div class="business-kpi"><span>本地客户</span><strong>${n.total}</strong></div><div class="business-kpi"><span>本机存储状态</span><strong style="font-size:15px;color:#159775">SQLite 正常</strong></div><div class="business-kpi"><span>最近快照</span><strong id="recentSnapshot" style="font-size:13px">读取中…</strong></div><div class="business-kpi"><span>运行模式</span><strong style="font-size:15px">完全离线</strong></div></div><div class="segment-summary" style="grid-template-columns:repeat(4,minmax(0,1fr))"><button class="summary-tile" data-action="import-csv"><span>导入客户 CSV / Excel</span><strong>＋</strong><small>本地处理</small></button><button class="summary-tile" data-action="export-all"><span>导出全部客户</span><strong>↓</strong><small>CSV 文件</small></button><button class="summary-tile" data-action="backup"><span>创建完整备份</span><strong>＋</strong><small>保存在本机</small></button><button class="summary-tile" data-action="download-template"><span>下载导入模板</span><strong>↓</strong><small>标准字段</small></button></div><div class="two-col-content"><section class="panel"><div class="panel-heading"><h2 class="panel-title">导入与同步</h2></div><div class="funnel-content"><p style="font-size:9px;color:#8490a0;line-height:1.7">CSV、Excel 与旧版 3.28.0 数据库均在本机识别。旧库只读，迁移需先预览并由你确认。</p><button class="btn" data-action="import-csv">${icons('upload')}选择 CSV / Excel 文件</button><button class="btn" data-action="import-legacy" style="margin-left:8px">${icons('database')}选择旧版数据库</button></div></section><section class="panel"><div class="panel-heading"><h2 class="panel-title">本地备份与迁移</h2></div><div class="funnel-content"><p style="font-size:9px;color:#8490a0;line-height:1.7">备份可带到其他电脑恢复。恢复前自动建立当前数据快照；旧数据库迁移也会先预览确认。</p><button class="btn primary" data-action="backup">${icons('cloud-down')}创建 JSON 备份</button><button class="btn" data-action="import-backup" style="margin-left:8px">${icons('upload')}从备份恢复</button><input type="file" id="importFile" accept=".csv,.tsv,.xlsx,.xls,.xlsm,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" hidden><input type="file" id="backupFile" accept=".json,application/json" hidden><input type="file" id="legacyDbFile" accept=".db,.sqlite,.sqlite3,application/octet-stream" hidden></div></section></div>`;loadSnapshotPanel();}
  function renderActivity(){const logs=state.activities.slice(0,30);$('#viewContainer').innerHTML=heading('操作记录','本地数据变更和自动化执行均在此留痕',btn('导出记录','download','export-activity'))+`<section class="panel table-panel"><div class="table-toolbar"><div class="table-context"><strong>最近操作</strong><span>${logs.length} 条真实记录</span></div><label class="input-search">${icons('search')}<input data-activity-search placeholder="搜索操作内容"></label></div><table class="task-table"><thead><tr><th>操作内容</th><th>操作类型</th><th>操作时间</th><th>来源</th></tr></thead><tbody>${logs.map(a=>`<tr data-activity-row><td><div class="activity-item" style="padding:2px 0"><i class="activity-dot"></i><div class="activity-text">${esc(a.text)}</div></div></td><td><span class="status-tag tag-blue">本地操作</span></td><td>${esc(a.time)}</td><td>本机工作台</td></tr>`).join('')||'<tr><td colspan="4" class="muted-cell">暂无操作记录</td></tr>'}</tbody></table></section>`;}
  function renderRecycle(){const list=state.customers.filter(c=>c.deleted);const pageCount=Math.max(1,Math.ceil(list.length/state.perPage));state.page=Math.min(state.page,pageCount);const start=(state.page-1)*state.perPage,visible=list.slice(start,start+state.perPage);$('#viewContainer').innerHTML=heading('回收站','移入回收站的客户仍保留在本机，可随时恢复',btn('清空回收站','x','empty-recycle','danger'))+`<section class="panel table-panel"><div class="table-toolbar"><div class="table-context"><strong>已删除客户</strong><span>${list.length} 条</span></div></div><div class="table-scroll"><table class="data-table"><thead><tr>${['客户','原始号码','渠道','页面','跟进助理','进群状态','阶段','登记日期','操作'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${visible.length?visible.map(c=>`<tr><td>${esc(c.name)}</td><td class="phone-cell">${esc(c.rawPhone)}</td><td>${sourceTag(c.source)}</td><td>${esc(c.page||'—')}</td><td>${esc(c.assistant)}</td><td>${statusTag(c.status)}</td><td>${phaseTag(c.phase)}</td><td>${esc(c.registered)}</td><td><button class="table-action" data-action="restore-customer" data-id="${esc(c.id)}">恢复</button></td></tr>`).join(''):`<tr><td colspan="9" style="text-align:center;padding:36px;color:#9aa4b1">回收站为空</td></tr>`}</tbody></table></div><div class="table-footer"><span>显示 ${list.length?start+1:0}–${Math.min(start+state.perPage,list.length)} 条，共 ${list.length} 条</span><div class="pagination"><button class="page-btn" data-page="${Math.max(1,state.page-1)}">‹</button><span>${state.page} / ${pageCount}</span><button class="page-btn" data-page="${Math.min(pageCount,state.page+1)}">›</button></div></div></section>`;}
  async function emptyRecycleWithSnapshot(){
    const recycled=state.customers.filter(customer=>customer.deleted);
    if(!recycled.length){toast('回收站已经为空');return;}
    const ids=new Set(recycled.map(customer=>selectionKey(customer.id)));
    const related={tickets:state.tickets.filter(row=>ids.has(selectionKey(row.customerId))).length,deposits:state.deposits.filter(row=>ids.has(selectionKey(row.customerId))).length,followups:state.followups.filter(row=>ids.has(selectionKey(row.customerId))).length,registrations:state.registrations.filter(row=>ids.has(selectionKey(row.customerId))).length};
    const relatedTotal=related.tickets+related.deposits+related.followups+related.registrations,detail=relatedTotal?`\n同时清除关联记录：跟票 ${related.tickets} 条、入金 ${related.deposits} 条、跟进 ${related.followups} 条、报名 ${related.registrations} 条。`:'';
    if(!confirm(`永久清除回收站中的 ${recycled.length} 位客户？${detail}\n此操作无法撤销，但会先创建本机快照。`))return;
    if(!await snapshotBeforeWrite('清空回收站前自动快照'))return;
    const before={customers:state.customers,tickets:state.tickets,deposits:state.deposits,followups:state.followups,registrations:state.registrations,activities:state.activities.slice()};
    state.customers=state.customers.filter(customer=>!ids.has(selectionKey(customer.id)));
    state.tickets=state.tickets.filter(row=>!ids.has(selectionKey(row.customerId)));
    state.deposits=state.deposits.filter(row=>!ids.has(selectionKey(row.customerId)));
    state.followups=state.followups.filter(row=>!ids.has(selectionKey(row.customerId)));
    state.registrations=state.registrations.filter(row=>!ids.has(selectionKey(row.customerId)));
    activity(`永久清空回收站，移除 ${recycled.length} 位客户及 ${relatedTotal} 条关联记录`);
    try{await flushStateWrites();}catch{Object.assign(state,before);persist();render();toast('清空保存失败，已恢复客户和所有关联记录','x');return;}
    render();toast(`已清空 ${recycled.length} 位客户及 ${relatedTotal} 条关联记录`);
  }
  async function passwordHash(value){const bytes=new TextEncoder().encode(String(value));const digest=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,'0')).join('');}
  async function clearAllDataWithSnapshot(){
    if(destructiveWriteBusy){toast('清空操作正在执行，请稍候');return;}
    const total=state.customers.length+state.tickets.length+state.deposits.length+state.followups.length+state.registrations.length+state.batchOperations.length;
    if(!total){toast('客户业务数据已经为空；独立手机号登记未包含在此操作中');return;}
    if(!state.settings.clearDataPasswordHash){toast('请先在“系统设置 → 安全与备份”中设置清空密码','x');securitySettingsModal();return;}
    const password=prompt(`将永久清空本机全库 ${total} 条业务数据。请输入清空密码：`);
    if(password==null)return;
    if(await passwordHash(password)!==state.settings.clearDataPasswordHash){toast('密码错误，未执行清空','x');return;}
    if(!confirm('密码验证通过。确定继续清空全库数据？'))return;
    if(!await snapshotBeforeWrite('清空全库前自动快照'))return;
    const before={customers:state.customers,tickets:state.tickets,deposits:state.deposits,followups:state.followups,registrations:state.registrations,batchOperations:state.batchOperations,activities:state.activities,savedViews:state.savedViews,importIssues:state.importIssues,qualityDecisions:state.qualityDecisions};
    destructiveWriteBusy=true;
    try{
      state.customers=[];state.tickets=[];state.deposits=[];state.followups=[];state.registrations=[];state.batchOperations=[];state.activities=[];state.importIssues=[];state.qualityDecisions={};state.savedViews=normalizeSavedViews([]);state.selected.clear();
      state.activities.unshift({text:'清空本机全库数据',time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),color:'green'});
      persist();
      await flushStateWrites();
      render();toast('本机全库数据已清空');
    }catch{
      Object.assign(state,before);persist();render();toast('清空保存失败，已恢复清空前的全部数据','x');
    }finally{
      destructiveWriteBusy=false;
    }
  }
