  function optionListModal(key){const item=optionCatalog[key];if(!item)return;const usage=value=>state.customers.filter(customer=>({sources:customer.source,groupFanSources:customer.source,assistants:customer.assistant,pages:customer.page,groupIds:customer.group,statuses:customer.status,phases:customer.phase}[key])===value).length;openModal(`管理${item.label}`,'所有选项均可修改。重命名会同步更新现有客户资料；删除不会清除历史数据。',`<div class="preview-table-wrap" style="max-height:300px"><table class="preview-table"><thead><tr><th>${item.label}</th><th>使用中</th><th>操作</th></tr></thead><tbody>${item.values.map(value=>`<tr><td>${esc(value)}</td><td>${usage(value)} 位客户</td><td><button class="table-action" data-option-edit="${key}" data-option-value="${esc(value)}">重命名</button> <button class="table-action danger-text" data-option-remove="${key}" data-option-value="${esc(value)}" ${item.values.length<=1?'disabled':''}>删除</button></td></tr>`).join('')||`<tr><td colspan="3" class="muted-cell">暂无选项，请添加或恢复默认项</td></tr>`}</tbody></table></div><div class="filter-grid" style="grid-template-columns:minmax(0,1fr) auto;margin-top:12px"><label class="filter-field"><span>新增${item.label}</span><input id="optionValue" maxlength="48" placeholder="输入名称"></label><button class="btn primary" data-action="add-option" data-option-key="${key}" style="align-self:end">添加</button></div>`,`<button class="btn" data-action="reset-options" data-option-key="${key}">恢复此类默认项</button><button class="btn" data-action="close-modal">完成</button>`);}
  async function renameOption(key,oldValue){const item=optionCatalog[key];if(!item||!item.values.includes(oldValue))return;const answer=prompt(`修改${item.label}名称：`,oldValue);if(answer===null)return;const value=answer.trim().slice(0,48);if(!value){toast('名称不能为空','x');return;}if(value.toLocaleLowerCase()!==oldValue.toLocaleLowerCase()&&item.values.some(option=>option.toLocaleLowerCase()===value.toLocaleLowerCase())){toast('此名称已存在','x');return;}if(value===oldValue){toast('名称没有变化');return;}if(!await snapshotBeforeWrite(`修改${item.label}选项前自动快照`))return;const field={sources:'source',groupFanSources:'source',assistants:'assistant',pages:'page',groupIds:'group',statuses:'status',phases:'phase'}[key],previous=state.customers.map(customer=>[customer,customer[field]]);item.values.splice(item.values.indexOf(oldValue),1,value);if(key==='groupFanSources'){const sourceIndex=sources.indexOf(oldValue);if(sourceIndex>=0)sources.splice(sourceIndex,1,value);else if(!sources.includes(value))sources.push(value);}for(const customer of state.customers)if(customer[field]===oldValue)customer[field]=value;persistOptionLists();activity(`重命名${item.label}选项：${oldValue} → ${value}`);try{await flushStateWrites();}catch{item.values.splice(item.values.indexOf(value),1,oldValue);if(key==='groupFanSources'){const sourceIndex=sources.indexOf(value);if(sourceIndex>=0)sources.splice(sourceIndex,1,oldValue);}for(const [customer,prior] of previous)customer[field]=prior;persistOptionLists();toast('选项修改未能保存，已还原','x');return;}optionListModal(key);render();toast(`已更新选项及相关客户资料：${value}`);}
  async function removeOption(key,value){const item=optionCatalog[key];if(!item||!item.values.includes(value)||item.values.length<=1)return;const field={sources:'source',groupFanSources:'source',assistants:'assistant',pages:'page',groupIds:'group',statuses:'status',phases:'phase'}[key],usage=state.customers.filter(customer=>customer[field]===value).length;if(usage&&!confirm(`“${value}”当前用于 ${usage} 位客户。删除选项不会清除这些客户资料，但后续筛选和录入将不再提供此项。继续删除？`))return;if(!await snapshotBeforeWrite(`删除${item.label}选项前自动快照`))return;const index=item.values.indexOf(value),sourceIndex=sources.indexOf(value);item.values.splice(index,1);if(key==='groupFanSources'&&!usage&&sourceIndex>=0)sources.splice(sourceIndex,1);persistOptionLists();activity(`删除${item.label}选项：${value}`);try{await flushStateWrites();}catch{item.values.splice(index,0,value);if(key==='groupFanSources'&&!sources.includes(value))sources.splice(sourceIndex<0?sources.length:sourceIndex,0,value);persistOptionLists();toast('选项删除未能保存，已还原','x');return;}optionListModal(key);render();toast(`已删除选项：${value}`);}
  async function resetOptionList(key){const item=optionCatalog[key];if(!item)return;if(!confirm(`将“${item.label}”恢复为随应用提供的默认选项？当前客户资料不会改变，用户自定义选项会移除。`))return;if(!await snapshotBeforeWrite(`恢复${item.label}默认选项前自动快照`))return;const before=[...item.values];item.values.splice(0,item.values.length,...defaultOptionLists[key]);persistOptionLists();activity(`恢复${item.label}默认选项`);try{await flushStateWrites();}catch{item.values.splice(0,item.values.length,...before);persistOptionLists();toast('恢复默认选项未能保存，已还原','x');return;}optionListModal(key);render();toast(`${item.label}已恢复默认选项`);}
  async function addOption(key){const item=optionCatalog[key],input=$('#optionValue'),raw=input?.value.trim();if(!item||!raw){toast('请输入要新增的选项');return;}const value=key==='groupIds'?raw.toUpperCase():raw;if(item.values.some(option=>option.toLocaleLowerCase()===value.toLocaleLowerCase())){toast('此选项已存在');return;}if(!await snapshotBeforeWrite(`新增${item.label}选项前自动快照`))return;item.values.push(value);persistOptionLists();activity(`新增${item.label}选项：${value}`);try{await flushStateWrites();}catch{item.values.pop();persistOptionLists();toast('选项新增未能保存，已还原','x');return;}optionListModal(key);render();toast(`已新增选项：${value}`);}
  function securitySettingsModal(){openModal('安全与备份','工作区随应用文件夹迁移；自动快照只保存在本机。',`<div class="filter-grid" style="grid-template-columns:1fr"><label class="filter-field"><span>本机快照保留数量</span><select id="snapshotRetention">${[10,20,30,50,100].map(value=>`<option value="${value}" ${Number(state.settings.snapshotRetention||20)===value?'selected':''}>最近 ${value} 个</option>`).join('')}</select></label><label class="column-choice"><input id="autoCloseSnapshot" type="checkbox" ${state.settings.autoCloseSnapshot===false?'':'checked'}><span>正常关闭应用时创建快照</span></label>${state.settings.clearDataPasswordHash?'<label class="filter-field"><span>当前清空密码</span><input id="clearDataOldPassword" type="password" maxlength="64" autocomplete="current-password" placeholder="修改密码时必须验证"></label>':''}<label class="filter-field"><span>${state.settings.clearDataPasswordHash?'新的清空密码':'设置清空全库密码'}</span><input id="clearDataPassword" type="password" maxlength="64" autocomplete="new-password" placeholder="${state.settings.clearDataPasswordHash?'留空表示不修改':'至少 6 位'}"></label><label class="filter-field"><span>再次输入新密码</span><input id="clearDataPasswordConfirm" type="password" maxlength="64" autocomplete="new-password" placeholder="请再输入一次"></label></div><div class="notice-line">修改清空密码必须先验证当前密码。密码只在本机保存不可逆摘要，不保存明文；恢复快照前也会自动保护当前数据。</div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-security-settings">保存设置</button>`);}
  async function saveSecuritySettings(){const password=$('#clearDataPassword')?.value||'',confirmation=$('#clearDataPasswordConfirm')?.value||'',oldPassword=$('#clearDataOldPassword')?.value||'';if(password||confirmation){if(state.settings.clearDataPasswordHash&&await passwordHash(oldPassword)!==state.settings.clearDataPasswordHash){toast('当前清空密码不正确，未修改密码','x');return;}if(password.length<6){toast('清空密码至少 6 位','x');return;}if(password!==confirmation){toast('两次输入的新密码不一致','x');return;}state.settings.clearDataPasswordHash=await passwordHash(password);}state.settings.snapshotRetention=Math.min(100,Math.max(10,Number($('#snapshotRetention').value)||20));state.settings.autoCloseSnapshot=$('#autoCloseSnapshot').checked;persist();activity(`更新本机快照与清空密码保护${password?'，已验证并更新密码':''}`);closeModal();render();toast('安全与备份设置已保存');}
