  function renderRegistrations(){const activeIds=new Set(activeCustomers().map(customer=>String(customer.id))),rows=state.registrations.filter(item=>item.status==='已报名'&&activeIds.has(String(item.customerId))).sort((a,b)=>String(b.date||b.createdAt).localeCompare(String(a.date||a.createdAt))),customerMap=new Map(activeCustomers().map(customer=>[String(customer.id),customer])),unique=new Set(rows.map(item=>String(item.customerId)));$('#viewContainer').innerHTML=heading('报名转化管理','报名状态默认为空；只有明确选择“已报名”才计入统计',`${btn('新增报名','plus','new-registration','primary')}${btn('导出报名','download','export-registrations')}`)+`<div class="business-summary"><div class="business-kpi"><span>已报名客户</span><strong>${unique.size}</strong></div><div class="business-kpi"><span>报名记录</span><strong>${rows.length}</strong></div><div class="business-kpi"><span>今日报名</span><strong>${rows.filter(r=>String(r.date).slice(0,10)===today).length}</strong></div><div class="business-kpi"><span>待跟进报名</span><strong>${rows.filter(r=>{const c=customerMap.get(String(r.customerId));return c&&(!c.lastFollow||c.lastFollow<String(r.date).slice(0,10));}).length}</strong></div></div><section class="panel table-panel"><div class="table-toolbar"><div class="toolbar-controls"><label class="input-search">${icons('search')}<input data-registration-search placeholder="搜索客户、来源、负责人、备注"></label><select data-registration-filter="source"><option value="全部">全部来源</option>${[...new Set(rows.map(r=>r.source).filter(Boolean))].map(v=>`<option>${esc(v)}</option>`).join('')}</select><select data-registration-filter="owner"><option value="全部">全部负责人</option>${assistants.map(v=>`<option>${esc(v)}</option>`).join('')}</select></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>报名时间</th><th>客户</th><th>号码</th><th>来源</th><th>负责人</th><th>备注</th><th>操作</th></tr></thead><tbody>${rows.map(row=>{const c=customerMap.get(String(row.customerId));return `<tr data-registration-row data-source="${esc(row.source||'')}" data-owner="${esc(row.owner||c?.assistant||'')}" data-search-text="${esc([c?.name,c?.phone,row.source,row.owner,row.note].join(' ').toLowerCase())}" data-customer="${esc(row.customerId)}"><td>${esc(String(row.date||row.createdAt||'').slice(0,16).replace('T',' '))}</td><td>${esc(c?.name||'未关联客户')}</td><td>${esc(c?.rawPhone||c?.phone||'—')}</td><td>${esc(row.source||'—')}</td><td>${esc(row.owner||c?.assistant||'未分配')}</td><td>${esc(row.note||'—')}</td><td><button class="table-action" data-customer="${esc(row.customerId)}">客户档案</button><button class="table-action danger-text" data-action="delete-registration-record" data-id="${esc(row.id)}">删除</button></td></tr>`;}).join('')||'<tr><td colspan="7" class="muted-cell">暂无报名记录</td></tr>'}</tbody></table></div></section>`;}

  function registrationModal(){const customers=activeCustomers();openModal('新增报名记录','报名信息将独立保存并关联客户档案',`<div class="filter-grid">${customerPickerHtml('registrationCustomer',customers,'','客户')}<label class="filter-field"><span>报名状态</span><select id="registrationStatus"><option value="">未选择（不计统计）</option><option value="已报名">已报名</option></select></label><label class="filter-field"><span>报名时间</span><input id="registrationDate" type="datetime-local" value="${new Date().toISOString().slice(0,16)}"></label><label class="filter-field"><span>报名来源</span><input id="registrationSource" placeholder="活动、页面或渠道"></label><label class="filter-field"><span>负责人</span><select id="registrationOwner">${assistants.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label><label class="filter-field" style="grid-column:1/-1"><span>备注</span><textarea id="registrationNote" rows="3"></textarea></label></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-registration">保存报名</button>`);}
  let modalReturnFocus=null;
  function openModal(title,subtitle,body,footer=''){modalReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;$('#modal').innerHTML=`<div class="modal-header"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="modal-close" data-action="close-modal" aria-label="关闭对话框">${icons('x')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;$('#modalBackdrop').classList.remove('hidden');$('#modal .modal-close')?.focus();}
  function globalSearchResults(query){const q=String(query||'').trim().toLocaleLowerCase(),digits=q.replace(/\D/g,'');if(q.length<2&&digits.length<2)return [];const best=[];for(const customer of state.customers){if(customer.deleted)continue;const values=[customer.name,customer.phone,customer.rawPhone,customer.group,customer.channel,customer.assistant,customer.note].map(value=>String(value||'').toLocaleLowerCase());let rank=0;if(values[0]===q)rank+=100;if(values[1]===digits||values[2].replace(/\D/g,'')===digits)rank+=95;if(values[0].startsWith(q))rank+=60;if(values[1].startsWith(digits)&&digits)rank+=55;if(values.some(value=>value.includes(q)))rank+=25;if(digits&&values[2].replace(/\D/g,'').includes(digits))rank+=25;if(!rank)continue;let index=best.findIndex(item=>rank>item.score||(rank===item.score&&String(customer.name).localeCompare(String(item.customer.name),'zh-CN')<0));if(index<0)index=best.length;best.splice(index,0,{customer,score:rank});if(best.length>20)best.pop();}return best.map(item=>item.customer);}
  function globalSearchResultsHtml(query){const q=String(query||'').trim(),results=globalSearchResults(q);if(q.length<2)return '<div class="global-search-empty">输入至少 2 个字符开始搜索</div>';if(!results.length)return '<div class="global-search-empty">没有找到匹配客户</div>';return `<div class="global-search-meta">显示最相关的 ${results.length} 条结果</div><div class="global-search-results">${results.map(customer=>`<button class="global-search-result" data-action="open-search-customer" data-id="${esc(customer.id)}"><div class="mini-avatar">${esc(customer.name?.[0]||'客')}</div><div><strong>${esc(customer.name)}</strong><span>${esc(customer.rawPhone)} · ${esc(customer.source)} · ${esc(customer.channel||'未识别')}</span></div><em>${esc(customer.group||'—')}</em></button>`).join('')}</div>`;}
  function globalSearchModal(query=''){openModal('全局客户搜索','姓名、号码、群编号、渠道、助理和备注联合匹配',`<label class="global-search-modal-input">${icons('search')}<input id="globalSearchInput" value="${esc(query)}" placeholder="输入姓名、号码、群编号等" autocomplete="off"></label><div id="globalSearchResults">${globalSearchResultsHtml(query)}</div>`,`<button class="btn" data-action="close-modal">关闭</button><button class="btn primary" data-action="open-search-list">在客户中心查看全部</button>`);const input=$('#globalSearchInput');input?.focus();if(input){input.setSelectionRange(input.value.length,input.value.length);}}
  function customerColumnsModal(mode){const visible=visibleCustomerColumns(mode);const choices=customerColumnDefs.filter(([, ,locked])=>!locked);openModal('客户表格列设置',`${mode==='customer'?'客户中心':'分类视图'}单独保存显示方案；客户、选择和操作列固定显示。`,`<div class="column-settings">${choices.map(([key,label])=>`<label class="column-choice"><input type="checkbox" data-column-option value="${key}" ${visible.has(key)?'checked':''}><span>${label}</span></label>`).join('')}</div><div class="column-settings-note">取消勾选可隐藏字段；筛选和导出仍使用完整客户资料。</div>`,`<button class="btn" data-action="columns-reset">恢复默认列</button><button class="btn primary" data-action="columns-apply" data-mode="${mode}">应用设置</button>`);}
  function shortcutHelpModal(){const rows=[['Ctrl + K','全局搜索客户'],['Ctrl + N','新增一位客户'],['Ctrl + Shift + I','打开快速录入'],['Ctrl + Shift + B','立即创建完整备份'],['Esc','关闭弹窗或客户详情']];openModal('快捷键与使用帮助','常用操作无需离开键盘，所有功能仍完全离线',`<div class="shortcut-list">${rows.map(([keys,label])=>`<div><kbd>${keys}</kbd><span>${label}</span></div>`).join('')}</div><div class="notice-line">建议首次录入后立即到“数据中心”创建一份 JSON 备份，并定期复制到其他安全位置。</div>`,`<button class="btn" data-action="close-modal">知道了</button>`);}
  function closeModal(){$('#modalBackdrop').classList.add('hidden');const target=modalReturnFocus;modalReturnFocus=null;if(target?.isConnected)target.focus();}
  function legacyPreviewModal(result){state.pendingLegacyToken=result.token;const statuses=Object.entries(result.statusCounts||{}).map(([k,v])=>`${esc(k)} ${v}`).join(' · ')||'—';const pages=Object.entries(result.pageCounts||{}).map(([k,v])=>`${esc(k)} ${v}`).join(' · ')||'—';openModal('确认迁移旧版数据库',`本机只读预览 · ${esc(result.filename||'所选文件')}`,`<div class="business-summary"><div class="business-kpi"><span>有效客户</span><strong>${result.customers}</strong></div><div class="business-kpi"><span>跟票</span><strong>${result.tickets}</strong></div><div class="business-kpi"><span>入金</span><strong>${result.deposits}</strong></div><div class="business-kpi"><span>跟进历史</span><strong>${result.followups}</strong></div><div class="business-kpi"><span>归档/合并未迁入客户</span><strong>${Number(result.excludedCustomers)||0}</strong></div><div class="business-kpi"><span>未关联历史跟进</span><strong>${Number(result.unlinkedFollowups)||0}</strong></div></div><p class="panel-note" style="line-height:1.8;margin:14px 0"><strong>进群状态：</strong>${statuses}<br><strong>来源分类：</strong>${pages}<br><strong>重复号码：</strong>${result.duplicatePhones}<br><strong>其中已归档：</strong>${Number(result.archivedCustomers)||0} · <strong>已合并：</strong>${Number(result.mergedCustomers)||0}</p><div class="notice-line">确认后将以旧库数据替换当前工作区，并在本机 SQLite 中自动建立迁移前快照。被合并客户的历史会尽量关联到合并后的客户；已归档或无法关联的历史仍会作为独立跟进记录保留。旧数据库只读，不会被修改。</div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="commit-legacy">确认并迁移</button>`);}
  async function importLegacyFile(file){if(!file)return;try{toast('正在本机检查所选数据库');const response=await fetch('/api/import/legacy/preview',{method:'POST',headers:{'Content-Type':'application/octet-stream','x-filename':file.name},body:await file.arrayBuffer()});const result=await response.json();if(!response.ok)throw new Error(result.error||'无法读取所选数据库');legacyPreviewModal(result);}catch(error){toast(error.message||'迁移预览失败','x');}}
  async function commitLegacy(){if(!state.pendingLegacyToken)return;const button=$('#modal [data-action="commit-legacy"]');if(button){button.disabled=true;button.textContent='正在迁移…';}try{await flushStateWrites();const response=await fetch('/api/import/legacy/commit',{method:'POST',headers:{'Content-Type':'application/json','X-State-Version':stateVersion},body:JSON.stringify({token:state.pendingLegacyToken})});const result=await response.json();if(!response.ok)throw new Error(result.error||'迁移失败');const loaded=await fetch('/api/state').then(r=>r.json());applySharedData(loaded);stateVersion=String(loaded.version||result.version||'');lastCommittedState=cloneStateData(statePayload());state.pendingLegacyToken=null;closeModal();persist();render();toast(`迁移完成：${result.customers} 位客户${result.snapshotCreated?'，迁移前快照已建立':''}`);}catch(error){if(button){button.disabled=false;button.textContent='确认并迁移';}toast(error.message||'迁移失败','x');}}
  function customerTimeline(customer){
    const phones=new Set(customerPhoneKeys(customer));const related=(record)=>record.customerId!=null?String(record.customerId)===String(customer.id):phones.has(linkedPhone(record.phone));
    const statusEvents=(Array.isArray(customer.statusHistory)?customer.statusHistory:[]).filter(event=>event&&['joined','left'].includes(event.type)&&event.date&&event.to).map(event=>({date:event.date,at:event.at||event.date,label:`${event.initial?'初始状态基线':'进退群状态变更'} · ${event.source||customer.source||'未分类'}`,detail:`${event.from||'新增资料'} → ${event.to}`,time:event.at&&Number.isFinite(Date.parse(event.at))?new Date(event.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):''}));
    const events=[...state.followups.filter(related).map(x=>({date:x.date,at:x.date,label:`跟进 · ${x.method||'未注明方式'}`,detail:x.result||x.note||'',next:x.nextDate})),...state.tickets.filter(related).map(x=>({date:x.date,at:x.date,label:'跟票记录',detail:`${x.product||'产品未注明'} · ${x.direction||'未注明方向'}${x.shares?` · ${x.shares} 股`:''}`})),...state.deposits.filter(related).map(x=>({date:x.date,at:x.date,label:'入金记录',detail:`${money(x.amount)} ${x.currency||''}`})),...statusEvents].sort((a,b)=>String(b.at||b.date||'').localeCompare(String(a.at||a.date||''))).slice(0,12);
    return events.map(x=>`<div class="timeline-row"><strong>${esc(x.label)}</strong><br>${esc(x.detail||'—')}<br><span class="panel-note">${esc(x.date||'未记录日期')}${x.time?` · ${esc(x.time)}`:''}${x.next?` · 登记日期 ${esc(x.next)}`:''}</span></div>`).join('')||`<div class="timeline-row">${esc(customer.note||'暂无跟进或业务记录')}<br><span class="panel-note">客户登记于 ${esc(customer.registered)}</span></div>`;
  }
  function closeCustomerDrawer(){document.querySelector('#customerDrawer')?.classList.remove('open');}
  function showCustomer(customer){if(!customer)return;const business=customerBusinessSummary(customer),crm=crmProfile(customer),favorite=Boolean(customer.favorite),dueClass=isValidDateKey(customer.due)&&customer.due<today?'tag-red':'tag-blue';let drawer=document.querySelector('#customerDrawer');if(!drawer){drawer=document.createElement('aside');drawer.id='customerDrawer';drawer.className='details-drawer customer-drawer';document.body.appendChild(drawer);}const fields=[['标准号码',customer.phone||'—'],['客户类型',customer.source||'—'],['来源渠道',customer.channel||customer.source||'—'],['页面分类',customer.page||'—'],['跟进助理',customer.assistant||'未分配'],['进群状态',customer.status||'—'],['客户阶段',customer.phase||'—'],['群编号',customer.group||'—'],['客户登记日期',customer.registered||'—'],['最后跟进',customer.lastFollow||'—'],['计划登记日期',customer.due||'—'],['是否股民',customer.investor?'是':'否']];drawer.innerHTML=`<div class="drawer-head customer-360-head"><div><span class="panel-note">客户 360° 档案 · 本机实时汇总</span><h2>${esc(customer.name)}</h2></div><div class="drawer-head-actions"><button class="favorite-button drawer-favorite ${favorite?'active':''}" data-action="toggle-favorite" data-id="${esc(customer.id)}" title="${favorite?'取消重点关注':'加入重点关注'}" aria-label="${favorite?'取消重点关注':'加入重点关注'}">★</button><button class="modal-close" data-action="close-customer-drawer" aria-label="关闭客户档案">${icons('x')}</button></div></div><div class="detail-hero customer-360-hero"><div class="detail-avatar">${esc(customer.name?.[0]||'客')}</div><div class="customer-360-identity"><strong>${esc(customer.name)}</strong><p>${esc(customer.rawPhone||customer.phone)} · ${esc(customer.source||'未分类')}${customer.page?` · ${esc(customer.page)}`:''}</p><div class="customer-360-tags">${favorite?'<span class="status-tag tag-amber">重点关注</span>':''}${customer.hot?'<span class="status-tag tag-coral">热聊</span>':''}${statusTag(customer.status)}${phaseTag(customer.phase)}</div></div></div><section class="customer-360-section"><div class="customer-360-section-title"><strong>CRM 指挥信息</strong><span>${crm.grade} 级 · ${crm.sla}</span></div><div class="crm-command"><div><span>CRM 评分</span><strong>${crm.score}</strong><small>${crm.grade} 级客户</small><div class="crm-score-track"><i style="width:${crm.score}%"></i></div></div><div><span>生命周期</span><strong>${esc(crm.stage)}</strong><small>累计跟进 ${crm.followCount} 次</small></div><div class="crm-next"><span>下一步建议</span><strong>${esc(crm.nextAction)}</strong><small>按客户状态与业务记录计算</small></div></div></section><section class="customer-360-section"><div class="customer-360-section-title"><strong>业务概览</strong><span>实时关联本机记录</span></div><div class="customer-360-business"><div><span>跟票状态</span><strong>${business.ticket?'已有跟票':'暂无跟票'}</strong></div><div><span>累计入金</span><strong>${business.deposit?money(business.amount):money(0)}</strong></div><div><span>登记日期</span><strong class="status-tag ${dueClass}">${esc(customer.due||'未安排')}</strong></div></div></section><section class="customer-360-section"><div class="customer-360-section-title"><strong>基础资料</strong><button class="link-button" data-action="edit-customer" data-id="${esc(customer.id)}">编辑资料</button></div><div class="detail-grid">${fields.map(([k,v])=>`<div class="detail-field"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}<div class="detail-field detail-field-editable"><span>资质评级</span><div class="qualification-editor"><select id="drawerQualification">${qualifications.map(value=>`<option ${value===(customer.qualification||'待评估')?'selected':''}>${esc(value)}</option>`).join('')}</select><button class="table-action" data-action="save-customer-qualification" data-id="${esc(customer.id)}">保存</button></div></div></div>${customer.note?`<div class="customer-360-note"><span>客户备注</span><p>${esc(customer.note)}</p></div>`:''}</section><section class="customer-360-section"><div class="customer-360-section-title"><strong>完整时间线</strong><span>最近 12 条</span></div><div class="timeline">${customerTimeline(customer)}</div></section><div class="drawer-actions customer-360-actions"><button class="btn" data-action="follow" data-id="${esc(customer.id)}">登记跟进</button><button class="btn" data-action="new-customer-ticket" data-id="${esc(customer.id)}">新增跟票</button><button class="btn" data-action="new-customer-deposit" data-id="${esc(customer.id)}">新增入金</button><button class="btn primary" data-action="edit-customer" data-id="${esc(customer.id)}">编辑资料</button></div>`;drawer.classList.add('open');}
  function editCustomerModal(customer){const field=(id,label,items,value)=>{const choices=[...new Set([...(items||[]),...(value&&!items.includes(value)?[value]:[])])];return `<label class="filter-field"><span>${label}</span><select id="${id}">${choices.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;};const pagesForEdit=[...new Set([...pages,...(customer.page?[customer.page]:[])])];openModal('编辑客户资料','人工修改字段会在后续导入时受到保护',`<div class="filter-grid" style="grid-template-columns:repeat(2,1fr)"><label class="filter-field"><span>客户姓名</span><input id="editName" value="${esc(customer.name)}"></label><label class="filter-field"><span>原始号码</span><input id="editPhone" value="${esc(customer.rawPhone)}"></label>${field('editSource','渠道',sources,customer.source)}${field('editPage','页面（可不选）',pagesForEdit,customer.page)}${field('editAssistant','跟进助理',assistants,customer.assistant)}${field('editStatus','进群状态',statuses,customer.status)}${field('editPhase','客户阶段',phases,customer.phase)}${field('editQualification','资质评级',qualifications,customer.qualification||'待评估')}<label class="filter-field"><span>群编号</span><input id="editGroup" value="${esc(customer.group==='—'?'':customer.group)}"></label><label class="filter-field" style="grid-column:1/-1"><span>备注</span><input id="editNote" value="${esc(customer.note)}"></label></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-customer" data-id="${customer.id}">保存修改</button>`);}
  function followModal(customer){const suggestedDays=smartFollowDays(customer);openModal('登记跟进',`${esc(customer.name)} · ${esc(customer.rawPhone)}`,`<div class="filter-grid" style="grid-template-columns:repeat(2,1fr)"><label class="filter-field"><span>跟进时间</span><input id="followDate" type="datetime-local" value="${new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}"></label><label class="filter-field"><span>跟进方式</span><select id="followMethod"><option>电话</option><option>WhatsApp</option><option>Telegram</option><option>群内沟通</option><option>其他</option></select></label><label class="filter-field"><span>报名状态</span><select id="followRegistration"><option value="">请选择</option><option value="未报名">未报名</option><option value="已报名">已报名</option></select></label><label class="filter-field" style="grid-column:1/-1"><span>跟进结果与备注</span><textarea id="followNote" class="intake-textarea" style="height:90px" placeholder="记录本次沟通结果"></textarea></label><label class="filter-field" style="grid-column:1/-1"><span>登记日期 · 智能建议 ${suggestedDays} 天后</span><input id="nextFollow" type="date" value="${localDateOffset(suggestedDays)}"></label></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-follow" data-id="${customer.id}">保存跟进</button>`);}
  function businessModal(type,customerId=''){const ticket=type==='ticket';openModal(ticket?'新增跟票':'新增入金','记录将保存到本机，并关联客户档案',`<div class="filter-grid" style="grid-template-columns:repeat(2,1fr)">${customerPickerHtml('businessCustomer',activeCustomers(),customerId,'客户') }<label class="filter-field"><span>${ticket?'跟票日期':'入金日期'}</span><input id="businessDate" type="date" value="${today}"></label>${ticket?`<label class="filter-field"><span>产品/代码</span><input id="businessProduct" placeholder="代码或产品名称"></label><label class="filter-field"><span>方向</span><select id="businessDirection"><option>买入</option><option>卖出</option><option>关注</option></select></label>`:`<label class="filter-field"><span>入金金额</span><input id="businessAmount" type="number" min="0" placeholder="金额"></label><label class="filter-field"><span>币种</span><select id="businessCurrency"><option>INR</option><option>USD</option><option>CNY</option></select></label>`}<label class="filter-field" style="grid-column:1/-1"><span>备注</span><input id="businessNote" placeholder="可选"></label></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-business" data-type="${type}">保存记录</button>`);}
  async function importTicketFile(file){if(!file)return;try{if(file.size>24*1024*1024)throw new Error('跟票文件超过 24 MB 上限');let tables=[];if(/\.xlsx?$|\.xlsm$/i.test(file.name)){if(!window.zhikeAI?.parseExcel)throw new Error('当前环境无法解析 Excel，请改用 CSV');const parsed=await window.zhikeAI.parseExcel({bytes:await file.arrayBuffer()});tables=(parsed.tables||[]).map(table=>({name:table.name,rows:table.rows||[]}));}else{const text=(await decodeCsvFile(file)).replace(/^\ufeff/,''),rows=parseCsv(text,detectCsvDelimiter(text));tables=[{name:file.name,rows}];}const customers=activeCustomers(),byPhone=new Map(customers.map(c=>[phoneForQuality(c),c]).filter(([phone])=>phone.length===10)),byName=new Map(customers.map(c=>[String(c.name||'').trim().toLocaleLowerCase(),c]).filter(([name])=>name)),known=new Set(state.tickets.map(r=>[String(r.customerId),String(r.date||''),String(r.product||'').toLocaleLowerCase(),String(r.direction||'')].join('|'))),valid=[],issues=[];for(const table of tables){if(table.rows.length<2)continue;const headers=table.rows[0].map(value=>String(value||'').trim().toLocaleLowerCase()),find=(...names)=>headers.findIndex(header=>names.some(name=>header===name||header.includes(name))),phoneIndex=find('号码','手机','电话','phone','mobile'),nameIndex=find('客户','姓名','name'),dateIndex=find('跟票日期','日期','date'),productIndex=find('产品','代码','股票','product','symbol'),directionIndex=find('方向','操作','direction'),noteIndex=find('备注','说明','note'),statusIndex=find('状态','status');if(phoneIndex<0&&nameIndex<0){issues.push(`${table.name}：未找到客户号码或姓名列`);continue;}for(let rowNumber=1;rowNumber<table.rows.length;rowNumber++){const row=table.rows[rowNumber],phone=phoneIndex>=0?linkedPhone(row[phoneIndex]):'',name=nameIndex>=0?String(row[nameIndex]||'').trim().toLocaleLowerCase():'',customer=byPhone.get(phone)||byName.get(name);if(!customer){issues.push(`${table.name} 第 ${rowNumber+1} 行：未匹配客户`);continue;}const date=normalizeImportedDate(dateIndex>=0?row[dateIndex]:'')||today,product=String(productIndex>=0?row[productIndex]:'').trim()||'未指定',direction=String(directionIndex>=0?row[directionIndex]:'').trim()||'关注',signature=[String(customer.id),date,product.toLocaleLowerCase(),direction].join('|');if(known.has(signature)){issues.push(`${table.name} 第 ${rowNumber+1} 行：跟票记录已存在`);continue;}known.add(signature);valid.push({id:`TI${Date.now()}-${valid.length}-${Math.random().toString(36).slice(2,6)}`,customerId:customer.id,customer:customer.name,phone:customer.rawPhone||customer.phone,date,product,direction,assistant:customer.assistant,channel:customer.channel||customer.source,group:customer.group,status:String(statusIndex>=0?row[statusIndex]:'').trim()||'已确认',note:String(noteIndex>=0?row[noteIndex]:'').trim().slice(0,2000)});}}if(!valid.length)throw new Error(issues[0]||'文件中没有可导入的跟票记录');if(!confirm(`跟票导入预览\n\n可导入：${valid.length} 条\n跳过/待检查：${issues.length} 条\n\n只会导入能匹配到现有客户的记录。继续？`))return;if(!await snapshotBeforeWrite('跟票文件导入前自动快照'))return;state.tickets=valid.concat(state.tickets);for(const record of valid){const customer=state.customers.find(c=>sameId(c.id,record.customerId));if(customer){customer.ticket=true;advanceCrm(customer,'ticket');}}persist();activity(`导入跟票 ${valid.length} 条，跳过 ${issues.length} 条`);await flushStateWrites();render();toast(`已导入 ${valid.length} 条跟票记录${issues.length?`，跳过 ${issues.length} 条`:''}`);}catch(error){toast(error.message||'跟票导入失败','x');}}
  function syncCustomerBusinessFlags(customerId){const customer=state.customers.find(c=>sameId(c.id,customerId));if(!customer)return;customer.ticket=state.tickets.some(r=>sameId(r.customerId,customer.id));const deposits=state.deposits.filter(r=>sameId(r.customerId,customer.id));customer.deposit=deposits.length>0;customer.amount=deposits.reduce((sum,r)=>sum+recordAmount(r),0);}
  async function deleteBusinessRecord(kind,id){const list=kind==='ticket'?state.tickets:state.deposits,index=list.findIndex(record=>sameId(record.id,id));if(index<0)return;const record=list[index],label=kind==='ticket'?'跟票':'入金';if(!confirm(`删除这条${label}记录？\n删除前会自动创建快照。`))return;if(!await snapshotBeforeWrite(`删除${label}记录前自动快照`))return;list.splice(index,1);syncCustomerBusinessFlags(record.customerId);persist();activity(`删除${label}记录：${record.customer||record.phone||record.id}`);try{await flushStateWrites();}catch{list.splice(index,0,record);syncCustomerBusinessFlags(record.customerId);persist();toast('删除失败，记录已恢复','x');return;}render();toast(`${label}记录已删除`);}
  function editBusinessRecord(kind,id){const list=kind==='ticket'?state.tickets:state.deposits,record=list.find(item=>sameId(item.id,id));if(!record)return;const ticket=kind==='ticket';openModal(ticket?'编辑跟票':'编辑入金','修改后会自动创建快照并校验完全重复记录',`<div class="filter-grid" style="grid-template-columns:repeat(2,1fr)"><label class="filter-field"><span>日期</span><input id="editBusinessDate" type="date" value="${esc(String(record.date||'').slice(0,10))}"></label>${ticket?`<label class="filter-field"><span>产品/代码</span><input id="editBusinessProduct" value="${esc(record.product||'未指定')}"></label><label class="filter-field"><span>方向</span><select id="editBusinessDirection"><option ${record.direction==='买入'?'selected':''}>买入</option><option ${record.direction==='卖出'?'selected':''}>卖出</option><option ${record.direction==='关注'?'selected':''}>关注</option></select></label>`:`<label class="filter-field"><span>金额</span><input id="editBusinessAmount" type="number" min="0" value="${esc(record.amount||0)}"></label><label class="filter-field"><span>币种</span><select id="editBusinessCurrency"><option ${record.currency==='INR'?'selected':''}>INR</option><option ${record.currency==='USD'?'selected':''}>USD</option><option ${record.currency==='CNY'?'selected':''}>CNY</option></select></label>`}<label class="filter-field" style="grid-column:1/-1"><span>备注</span><input id="editBusinessNote" value="${esc(record.note||'')}"></label></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-business-edit" data-kind="${kind}" data-id="${esc(record.id)}">保存修改</button>`);}
  async function saveBusinessEdit(kind,id){const list=kind==='ticket'?state.tickets:state.deposits,record=list.find(item=>sameId(item.id,id));if(!record)return;const next={...record,date:$('#editBusinessDate').value,note:$('#editBusinessNote').value.trim()};if(!/^\d{4}-\d{2}-\d{2}$/.test(next.date||'')){toast('请选择有效日期','x');return;}if(kind==='ticket'){next.product=$('#editBusinessProduct').value.trim()||'未指定';next.direction=$('#editBusinessDirection').value;}else{next.amount=Number($('#editBusinessAmount').value);next.currency=$('#editBusinessCurrency').value;if(!Number.isFinite(next.amount)||next.amount<=0){toast('请输入有效入金金额','x');return;}}if(list.some(item=>!sameId(item.id,id)&&businessRecordSignature(item,kind)===businessRecordSignature(next,kind))){toast(`完全相同的${kind==='ticket'?'跟票':'入金'}记录已存在，未保存修改`,'x');return;}if(!await snapshotBeforeWrite(`编辑${kind==='ticket'?'跟票':'入金'}记录前自动快照`))return;const before=cloneStateData(record);Object.assign(record,next);if(kind==='deposit'){const customer=state.customers.find(c=>sameId(c.id,record.customerId));if(customer){customer.amount=(Number(customer.amount)||0)-Number(before.amount||0)+Number(record.amount||0);}}persist();activity(`修改${kind==='ticket'?'跟票':'入金'}记录：${record.customer||record.phone||record.id}`);try{await flushStateWrites();}catch{Object.assign(record,before);persist();toast('保存失败，业务记录已恢复','x');render();return;}closeModal();render();toast('业务记录已保存');}
  async function deleteRegistrationRecord(id){const index=state.registrations.findIndex(record=>sameId(record.id,id));if(index<0)return;const record=state.registrations[index],customer=state.customers.find(c=>sameId(c.id,record.customerId));if(!confirm(`删除 ${customer?.name||'该客户'} 的这条报名记录？\n删除前会自动创建快照。`))return;if(!await snapshotBeforeWrite('删除报名记录前自动快照'))return;state.registrations.splice(index,1);if(customer&&!state.registrations.some(item=>sameId(item.customerId,customer.id)&&item.status==='已报名'))customer.registration='';persist();activity(`删除报名记录：${customer?.name||record.customerId}`);try{await flushStateWrites();}catch{state.registrations.splice(index,0,record);if(customer)customer.registration='已报名';persist();toast('删除失败，报名记录已恢复','x');return;}renderRegistrations();toast('报名记录已删除');}
  function batchModal(type){if(!state.selected.size){toast('请先选择客户');return;}const label={assistant:'分配助理',status:'修改进群状态',follow:'批量排期',hot:'标记热聊',qualification:'批量修改评级',registration:'批量报名状态',phase:'批量客户阶段',tag:'批量添加标签'}[type];let field='';if(type==='assistant')field=`<label class="filter-field"><span>选择助理</span><select id="batchValue">${assistants.map(x=>`<option>${x}</option>`).join('')}</select></label>`;if(type==='status')field=`<label class="filter-field"><span>选择状态</span><select id="batchValue">${statuses.map(x=>`<option>${x}</option>`).join('')}</select></label>`;if(type==='follow')field=`<label class="filter-field"><span>跟进日期</span><input id="batchValue" type="date" value="${localDateOffset(1)}"></label>`;if(type==='hot')field=`<label class="filter-field"><span>热聊状态</span><select id="batchValue"><option value="true">标记为热聊</option><option value="false">取消热聊</option></select></label>`;if(type==='qualification')field=`<label class="filter-field"><span>目标评级</span><select id="batchValue">${qualifications.map(x=>`<option>${x}</option>`).join('')}</select></label>`;if(type==='registration')field=`<label class="filter-field"><span>报名状态</span><select id="batchValue"><option value="已报名">已报名</option><option value="未报名">清空报名状态</option></select></label>`;if(type==='phase')field=`<label class="filter-field"><span>客户阶段</span><select id="batchValue">${phases.map(x=>`<option>${x}</option>`).join('')}</select></label>`;if(type==='tag')field=`<label class="filter-field"><span>添加标签</span><input id="batchValue" maxlength="30" placeholder="输入标签"></label>`;openModal(label,'先预览影响范围，再执行修改',`${field}<div class="notice-line">已选择 ${state.selected.size} 位客户。下一步不会立即写入数据。</div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="preview-batch" data-type="${type}">预览变更</button>`);}
  function batchFieldValue(customer,type){if(type==='assistant')return customer.assistant||'未分配';if(type==='status')return customer.status||'未记录';if(type==='follow')return customer.due||'未安排';if(type==='qualification')return customer.qualification||'未评级';if(type==='registration')return customer.registration||'未报名';if(type==='phase')return customer.phase||'未设置';if(type==='tag')return (customer.tags||[]).join('、')||'无标签';return customer.hot?'热聊':'非热聊';}
  function batchNextValue(type,value){return type==='hot'?(value==='true'?'热聊':'非热聊'):value;}
  function previewBatch(type){const value=$('#batchValue')?.value;if(!value){toast('请选择要修改的值','x');return;}const selected=state.customers.filter(customer=>!customer.deleted&&state.selected.has(customer.id)),next=batchNextValue(type,value),changed=selected.filter(customer=>batchFieldValue(customer,type)!==next),unchanged=selected.length-changed.length,label={assistant:'分配助理',status:'修改进群状态',follow:'批量排期',hot:'调整热聊'}[type];state.pendingBatch={type,value,ids:selected.map(customer=>customer.id)};const distribution=new Map();for(const customer of selected){const current=batchFieldValue(customer,type);distribution.set(current,(distribution.get(current)||0)+1);}const before=[...distribution.entries()].sort((a,b)=>b[1]-a[1]);const names=changed.slice(0,8).map(customer=>`<span class="batch-preview-name">${esc(customer.name)} · ${esc(batchFieldValue(customer,type))} → ${esc(next)}</span>`).join('');openModal(`确认${label}`,'仅修改真正发生变化的记录',`<div class="batch-preview-summary"><div><span>已选择</span><strong>${selected.length}</strong></div><div><span>将变更</span><strong>${changed.length}</strong></div><div><span>保持不变</span><strong>${unchanged}</strong></div></div><div class="batch-preview-target"><span>目标值</span><strong>${esc(next)}</strong></div><div class="batch-preview-distribution"><strong>当前分布</strong>${before.map(([current,count])=>`<span>${esc(current)} <b>${count}</b></span>`).join('')}</div><div class="batch-preview-list"><strong>变更预览${changed.length>8?`（前 8 位，共 ${changed.length} 位）`:''}</strong>${names||'<span class="muted-cell">没有记录需要修改</span>'}</div>${type==='status'&&changed.length?'<div class="notice-line">状态历史只记录实际进群/退群变化；相同状态不会重复计数。</div>':''}`,`<button class="btn" data-action="batch-${type}">返回调整</button><button class="btn primary" data-action="apply-batch" data-type="${type}" ${changed.length?'':'disabled'}>确认并执行</button>`);}
  function download(name,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function csvCell(value){const text=String(value??'');const safe=/^[\t\r\n ]*[=+\-@]/.test(text)?`'${text}`:text;return `"${safe.replace(/"/g,'""')}"`;}
  function exportCustomers(list,name='customers.csv'){const cols=['name','rawPhone','phone','source','page','assistant','status','phase','qualification','hot','investor','group','ticket','deposit','amount','registered','lastFollow','due','note'];const labels=['客户姓名','原始号码','标准号码','渠道','页面分类','跟进助理','进群状态','客户阶段','资质评级','热聊','是否股民','群编号','跟票','入金','入金金额','登记时间','最后跟进','登记日期','备注'];const business=businessSummaryIndex();const csv=[labels.join(','),...list.map(customer=>{const summary=customerBusinessSummary(customer,business);const values={...customer,qualification:customer.qualification||'待评估',ticket:summary.ticket?'是':'否',deposit:summary.deposit?'是':'否',amount:summary.amount};return cols.map(key=>csvCell(values[key])).join(',');})].join('\r\n');download(name,'\ufeff'+csv,'text/csv;charset=utf-8');toast(`已导出 ${list.length} 条客户记录`,'download');}
  function exportCsvRows(name,headers,rows,label='条记录'){const csv=[headers.map(csvCell).join(','),...rows.map(row=>row.map(csvCell).join(','))].join('\r\n');download(name,'\ufeff'+csv,'text/csv;charset=utf-8');toast(`已导出 ${rows.length} ${label}`,'download');}
  function currentModuleSearch(){return ($('#viewContainer [data-search="module"]')?.value||'').trim().toLocaleLowerCase();}
  function matchesExportSearch(values,query){return !query||values.some(value=>String(value??'').toLocaleLowerCase().includes(query));}
  function exportSimpleCustomerList(list,name){const query=currentModuleSearch();const rows=list.filter(c=>matchesExportSearch([c.name,c.rawPhone,c.source,c.channel,c.assistant,c.phase,c.due,c.note],query));exportCsvRows(name,['客户','号码','数据归属','来源渠道','跟进助理','客户阶段','计划日期','跟进内容'],rows.map(c=>[c.name,c.rawPhone,c.source,c.channel,c.assistant,c.phase,c.due,c.note]),'位客户');}
  function exportFollowups(){const tab=state.followTab||'open';if(tab==='done'){const events=[...state.followups].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));const rows=events.map(event=>{const customer=state.customers.find(c=>String(c.id)===String(event.customerId));return [customer?.name||event.customer||'客户记录',customer?.rawPhone||event.phone||'',event.date||'',event.method||'',event.result||event.note||'',event.nextDate||''];});exportCsvRows('已完成跟进.csv',['客户','号码','跟进时间','方式','结果与备注','登记日期'],rows);return;}const seven=localDateOffset(7);const list=activeCustomers().filter(c=>tab==='none'?(!c.due||c.due==='—'):c.due&&c.due!=='—'&&(tab==='overdue'?c.due<today:tab==='today'?c.due===today:tab==='week'?c.due>today&&c.due<=seven:c.due<=today)).sort((a,b)=>(a.due||'').localeCompare(b.due||''));exportSimpleCustomerList(list,`跟进${{open:'待处理',overdue:'已逾期',today:'今日',week:'未来7天',none:'未安排'}[tab]||'清单'}.csv`);}
  function exportHotCustomers(){const all=activeCustomers().filter(c=>c.hot),business=businessSummaryIndex();const filter=state.hotFilter||'all';const list=filter==='stale'?staleHotCustomers():filter==='today'?all.filter(c=>c.registered===today):filter==='not-joined'?all.filter(c=>!['已进群','在群'].includes(c.status)):filter==='not-deposit'?all.filter(c=>!customerBusinessSummary(c,business).deposit):all;exportSimpleCustomerList(list,'热聊客户.csv');}
