  async function applyBatch(type){const pending=state.pendingBatch;if(!pending||pending.type!==type){toast('批量预览已失效，请重新操作','x');return;}const ids=new Set(pending.ids),value=pending.value,next=batchNextValue(type,value),targets=state.customers.filter(customer=>ids.has(customer.id)&&!customer.deleted&&batchFieldValue(customer,type)!==next);if(!targets.length){state.pendingBatch=null;closeModal();toast('没有记录需要修改');return;}const label={assistant:'分配助理',status:'修改状态',follow:'安排跟进',hot:'调整热聊'}[type];if(!await snapshotBeforeWrite(`批量${label}前自动快照`))return;const rows=targets.map(customer=>({before:cloneStateData(customer),afterValue:next}));for(const customer of targets){if(type==='assistant')customer.assistant=value;if(type==='status')customer.status=recordCustomerStatus(customer,value);if(type==='follow')customer.due=value;if(type==='hot')customer.hot=value==='true';customer.touched=true;}const afterById=new Map(targets.map(customer=>[customer.id,cloneStateData(customer)]));for(const row of rows)row.after=afterById.get(row.before.id);state.lastBatchUndo={label,type,rows,createdAt:new Date().toISOString()};state.pendingBatch=null;state.selected.clear();persist();activity(`批量${label} ${targets.length} 位客户`);closeModal();render();toast(`已更新 ${targets.length} 位客户，可在表格底部撤销`);}
