  function saveCurrentView(mode){const scope=mode==='segment'?'segment':'customer';const custom=state.savedViews.filter(view=>view.scope===scope&&!view.builtin);if(custom.length>=50){toast('此区域最多保存 50 个自定义视图');return;}const answer=prompt('为当前筛选视图命名（最多 32 个字符）：');if(answer===null)return;const name=answer.trim().slice(0,32);if(!name){toast('视图名称不能为空');return;}if(state.savedViews.some(view=>view.scope===scope&&view.name.toLocaleLowerCase()===name.toLocaleLowerCase())){toast('此区域已有同名视图');return;}const filters=scope==='customer'?{...state.extraFilters}:{...state.segment};const search=scope==='customer'?state.customerSearch:state.search;state.savedViews.push({id:`view-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`,name,scope,filters,search,builtin:false});activity(`保存${scope==='customer'?'客户中心':'分类视图'}：${name}`);render();toast(`已保存视图：${name}`);}
